const input = $('When Executed by Another Workflow').first().json;
const email = String(input.email || '').trim().toLowerCase();
const digits = (v) => String(v || '').replace(/\D/g, '');
const phone = digits(input.phone);
if (!email && phone.length < 7) {
  return [{ json: { success: false, found: false, message: 'Please provide an email address or phone number to look up the customer.' } }];
}
const customers = $('Get Customers').all().map(i => i.json).filter(r => r.Email || r.Phone);
const customer = customers.find(r => (email && String(r.Email || '').trim().toLowerCase() === email) || (phone.length >= 7 && digits(r.Phone).endsWith(phone.slice(-10))));
if (!customer) {
  return [{ json: { success: true, found: false, message: 'This is a new client. They do not exist in the CRM yet. Collect full name, email, phone and vehicle details, then register them.' } }];
}
const cEmail = String(customer.Email || '').trim().toLowerCase();
const bookings = $('Get Bookings').all().map(i => i.json).filter(b => String(b.Email || '').trim().toLowerCase() === cEmail);
const now = Date.now();
const upcoming = bookings.filter(b => b.Status !== 'Cancelled' && new Date(b.Start).getTime() > now);
const vehicle = [customer['Vehicle Year'], customer['Vehicle Make'], customer['Vehicle Model']].filter(Boolean).join(' ');
return [{ json: {
  success: true,
  found: true,
  customer: { customerId: customer['Customer ID'], name: customer.Name, email: customer.Email, phone: String(customer.Phone || ''), vehicle, vehicleType: customer['Vehicle Type'] || '', registration: customer.Registration || '' },
  totalBookings: bookings.length,
  upcomingBookings: upcoming.map(b => ({ bookingId: b['Booking ID'], service: b.Service || b.Package, start: b.Start, status: b.Status })),
  message: bookings.length ? `Returning customer ${customer.Name} with ${bookings.length} previous booking(s) and ${upcoming.length} upcoming.` : `This client exists in the CRM (${customer.Name}) but has no previous appointments with Hercules Detailing.`
} }];
